    77:     /// The lowest and highest address this prefix may allocate.
    78:     ///
    79:     /// Network and broadcast are excluded wherever the prefix is wide enough to
    80:     /// have them: a /30 is exactly network, two hosts, broadcast.
    81:     ///
    82:     /// Computed in `u64` because a /0 spans all 2^32 addresses, whose last
    83:     /// address is `u32::MAX`. Doing this arithmetic in `u32` wraps a prefix
    84:     /// whose size is a multiple of 2^32 down to an empty one.
    85:     fn usable_bounds(&self) -> Result<(u32, u32), AllocationError> {
    86:         let size = 1u64 << (32 - u32::from(self.prefix_len));
    87:         let base = u64::from(u32::from(self.prefix));
    88:         let last = base
    89:             .checked_add(size - 1)
    90:             .filter(|last| *last <= u64::from(u32::MAX))
    91:             .ok_or(AllocationError::PrefixTooSmall(self.prefix_len))? as u32;
